-- Rebuild Medina Book 3 lesson 16 strictly from the supplied Arabic sharh.
-- The sharh combines lessons 16-17 under one heading. Lesson 16 is delimited through the material immediately before "ثانياً: باب أفعل" on PDF page 68.
-- Canonical page references: Sharkh_Medinskiy_3.pdf, PDF pages 65-68.
-- The Qur'anic text hidden by DOC control characters was transcribed literally from visible PDF page 67.

begin;
do $migration$
declare old_rule_count integer; new_rule_count integer; source_count integer;
begin
  select count(*) into old_rule_count from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '16';
  if old_rule_count <> 4 then raise exception 'Expected 4 generated Book 3 lesson 16 rules, found %', old_rule_count; end if;

  delete from public.rule_sections where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '16');
  delete from public.rule_sources where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '16');
  delete from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '16';

  insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar)
  values
    ('Мединский курс (Том 3)', '16', 'الْأَفْعَالُ الْمُجَرَّدَةُ وَالْمَزِيدَةُ (простые и производные глаголы)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Определения</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّعْرِيفُ</span><span class="rule-table-ru">определение</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَقْسَامُهُ</span><span class="rule-table-ru">разновидности</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْفِعْلُ الْمُجَرَّدُ</span><span class="rule-table-ru">простой глагол</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَا كَانَتْ جَمِيعُ أَحْرُفِهِ أَصْلِيَّةً</span><span class="rule-table-ru">глагол, все буквы которого являются коренными</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ثُلَاثِيٌّ وَرُبَاعِيٌّ</span><span class="rule-table-ru">трёхбуквенный и четырёхбуквенный</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْفِعْلُ الْمَزِيدُ</span><span class="rule-table-ru">производный глагол</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَا زِيدَ فِيهِ حَرْفٌ أَوْ أَكْثَرُ عَلَى أَحْرُفِهِ الْأَصْلِيَّةِ</span><span class="rule-table-ru">глагол, к коренным буквам которого добавлена одна или несколько букв</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ثُلَاثِيٌّ مَزِيدٌ وَرُبَاعِيٌّ مَزِيدٌ</span><span class="rule-table-ru">производный от трёхбуквенного и производный от четырёхбуквенного</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Простой трёхбуквенный глагол</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">خَرَجَ</span><span class="rule-table-ru">вышел</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فَهِمَ</span><span class="rule-table-ru">понял</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">كَرُمَ</span><span class="rule-table-ru">был благородным</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">قَرَأَ</span><span class="rule-table-ru">прочитал</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سَعَى</span><span class="rule-table-ru">стремился</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">نَامَ</span><span class="rule-table-ru">спал</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Замечание автора</span><p class="rule-study-text"><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">جَمِيعُ الْأَحْرُفِ الثَّلَاثَةِ أَصْلِيَّةٌ.</span> Все три буквы являются коренными.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Простой четырёхбуквенный глагол</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وَسْوَسَ</span><span class="rule-table-ru">нашёптывал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">زَلْزَلَ</span><span class="rule-table-ru">сотрясал</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَعْثَرَ</span><span class="rule-table-ru">разбросал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">دَحْرَجَ</span><span class="rule-table-ru">покатил</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَرْجَمَ</span><span class="rule-table-ru">перевёл</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جَمِيعُ الْأَحْرُفِ الْأَرْبَعَةِ أَصْلِيَّةٌ</span><span class="rule-table-ru">все четыре буквы являются коренными</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Производные глаголы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">все примеры автора с переводом</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُلَاحَظَةٌ</span><span class="rule-table-ru">замечание</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ثُلَاثِيٌّ مَزِيدٌ</span><span class="rule-table-ru">производный от трёхбуквенного</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سَلَّمَ، أَسْلَمَ، سَاعَدَ، تَقَبَّلَ، ٱسْتَقْبَلَ</span><span class="rule-table-ru">поприветствовал; принял ислам; помог; принял; встретил</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">زِيدَ فِيهِ حَرْفٌ أَوْ أَكْثَرُ</span><span class="rule-table-ru">добавлена одна или несколько букв</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">رُبَاعِيٌّ مَزِيدٌ</span><span class="rule-table-ru">производный от четырёхбуквенного</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَتَدْرُسُهُ فِي الْجُزْءِ الرَّابِعِ</span><span class="rule-table-ru">он будет изучаться в четвёртой части</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُجَرَّدُ وَالْمَزِيدُ</span><span class="rule-table-ru">и простой, и производный четырёхбуквенный глагол</span></td></tr></tbody></table></div></div></div>', 1, 'rule', 'Простой глагол состоит только из коренных букв, а производный содержит одну или несколько добавочных букв; оба вида бывают трёх- и четырёхбуквенными.', 'الْفِعْلُ الْمُجَرَّدُ مَا كَانَتْ جَمِيعُ أَحْرُفِهِ أَصْلِيَّةً، وَهُوَ ثُلَاثِيٌّ أَوْ رُبَاعِيٌّ. وَالْفِعْلُ الْمَزِيدُ مَا زِيدَ فِيهِ حَرْفٌ أَوْ أَكْثَرُ عَلَى أَحْرُفِهِ الْأَصْلِيَّةِ، وَهُوَ ثُلَاثِيٌّ مَزِيدٌ أَوْ رُبَاعِيٌّ مَزِيدٌ.'),
    ('Мединский курс (Том 3)', '16', 'أَوْزَانُ الثُّلَاثِيِّ الْمُجَرَّدِ (модели простого трёхбуквенного глагола)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">لِلثُّلَاثِيِّ الْمُجَرَّدِ بِاعْتِبَارِ <span class="ar-tone-verb">مَاضِيهِ</span> ثَلَاثَةُ أَبْوَابٍ، وَبِاعْتِبَارِ <span class="ar-tone-verb">الْمَاضِي مَعَ الْمُضَارِعِ</span> سِتَّةُ أَبْوَابٍ.</span><p class="rule-study-text">Если учитывать только прошедшее время, моделей три; если сопоставлять прошедшее и настоящее-будущее, моделей шесть.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Шесть моделей</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْوَزْنُ فِي الْمَاضِي</span><span class="rule-table-ru">модель прошедшего</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْوَزْنُ فِي الْمُضَارِعِ</span><span class="rule-table-ru">модель настоящего-будущего</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فَعَلَ</span><span class="rule-table-ru">фа‘аля</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَفْعُلُ</span><span class="rule-table-ru">яф‘улю</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">دَخَلَ: يَدْخُلُ؛ قَالَ: يَقُولُ</span><span class="rule-table-ru">вошёл — входит; сказал — говорит</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فَعَلَ</span><span class="rule-table-ru">фа‘аля</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَفْعِلُ</span><span class="rule-table-ru">яф‘илю</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">جَلَسَ: يَجْلِسُ؛ رَمَى: يَرْمِي</span><span class="rule-table-ru">сел — садится; бросил — бросает</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فَعَلَ</span><span class="rule-table-ru">фа‘аля</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَفْعَلُ</span><span class="rule-table-ru">яф‘алю</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ذَهَبَ: يَذْهَبُ؛ سَعَى: يَسْعَى</span><span class="rule-table-ru">ушёл — уходит; стремился — стремится</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فَعِلَ</span><span class="rule-table-ru">фа‘иля</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَفْعَلُ</span><span class="rule-table-ru">яф‘алю</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">شَرِبَ: يَشْرَبُ؛ رَضِيَ: يَرْضَى</span><span class="rule-table-ru">выпил — пьёт; был доволен — бывает доволен</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فَعِلَ</span><span class="rule-table-ru">фа‘иля</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَفْعِلُ</span><span class="rule-table-ru">яф‘илю</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وَرِثَ: يَرِثُ؛ حَسِبَ: يَحْسِبُ</span><span class="rule-table-ru">унаследовал — наследует; считал — считает</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فَعُلَ</span><span class="rule-table-ru">фа‘уля</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَفْعُلُ</span><span class="rule-table-ru">яф‘улю</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">كَثُرَ: يَكْثُرُ؛ جَرُؤَ: يَجْرُؤُ</span><span class="rule-table-ru">стал многочисленным — умножается; осмелел — осмеливается</span></td></tr></tbody></table></div></div></div>', 2, 'rule', 'У простого трёхбуквенного глагола три модели прошедшего времени и шесть сочетаний прошедшего с настоящим-будущим.', 'لِلثُّلَاثِيِّ الْمُجَرَّدِ بِاعْتِبَارِ مَاضِيهِ ثَلَاثَةُ أَبْوَابٍ، وَبِاعْتِبَارِ الْمَاضِي مَعَ الْمُضَارِعِ سِتَّةُ أَبْوَابٍ.'),
    ('Мединский курс (Том 3)', '16', 'أَقْسَامُ الثُّلَاثِيِّ الْمَزِيدِ (разряды производного трёхбуквенного глагола)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Три разряда</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْقِسْمُ</span><span class="rule-table-ru">разряд</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الزِّيَادَةُ</span><span class="rule-table-ru">количество добавочных букв</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُلَاحَظَةُ الْمُؤَلِّفِ</span><span class="rule-table-ru">замечание автора</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَزِيدٌ بِحَرْفٍ وَاحِدٍ</span><span class="rule-table-ru">производный с одной добавочной буквой</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَرْفٌ وَاحِدٌ</span><span class="rule-table-ru">одна буква</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">يُدْرَسُ فِي هَذَا الْجُزْءِ</span><span class="rule-table-ru">изучается в этой части</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَزِيدٌ بِحَرْفَيْنِ</span><span class="rule-table-ru">производный с двумя добавочными буквами</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَرْفَانِ</span><span class="rule-table-ru">две буквы</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَتَدْرُسُهُ فِي الْجُزْءِ الرَّابِعِ</span><span class="rule-table-ru">будет изучаться в четвёртой части</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَزِيدٌ بِثَلَاثَةِ أَحْرُفٍ</span><span class="rule-table-ru">производный с тремя добавочными буквами</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ثَلَاثَةُ أَحْرُفٍ</span><span class="rule-table-ru">три буквы</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَتَدْرُسُهُ فِي الْجُزْءِ الرَّابِعِ</span><span class="rule-table-ru">будет изучаться в четвёртой части</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Модели с одной добавочной буквой</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْبَابُ</span><span class="rule-table-ru">модель</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَالُ الدِّرَاسَةِ</span><span class="rule-table-ru">где изучается</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَابُ فَعَّلَ</span><span class="rule-table-ru">модель фа‘‘аля</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فِي هَذَا الْجُزْءِ</span><span class="rule-table-ru">в этой части</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَابُ أَفْعَلَ</span><span class="rule-table-ru">модель аф‘аля</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فِي هَذَا الْجُزْءِ</span><span class="rule-table-ru">в этой части</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَابُ فَاعَلَ</span><span class="rule-table-ru">модель фа‘аля с долгой первой гласной</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فِي الْجُزْءِ الرَّابِعِ</span><span class="rule-table-ru">в четвёртой части</span></td></tr></tbody></table></div></div></div>', 3, 'rule', 'Производный трёхбуквенный глагол бывает с одной, двумя или тремя добавочными буквами; у производного с одной добавочной буквой три модели.', 'الثُّلَاثِيُّ الْمَزِيدُ ثَلَاثَةُ أَقْسَامٍ: مَزِيدٌ بِحَرْفٍ وَاحِدٍ، وَمَزِيدٌ بِحَرْفَيْنِ، وَمَزِيدٌ بِثَلَاثَةِ أَحْرُفٍ. الْمَزِيدُ بِحَرْفٍ وَاحِدٍ لَهُ ثَلَاثَةُ أَبْوَابٍ: فَعَّلَ، وَأَفْعَلَ، وَفَاعَلَ.'),
    ('Мединский курс (Том 3)', '16', 'بَابُ فَعَّلَ وَمَصْدَرُهُ وَمُشْتَقَّاتُهُ (модель فَعَّلَ, её масдар и производные)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Основа модели</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْبَيَانُ</span><span class="rule-table-ru">пункт</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْقَاعِدَةُ</span><span class="rule-table-ru">правило и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مِنْ أَمْثِلَتِهِ</span><span class="rule-table-ru">примеры модели</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سَلَّمَ، سَبَّحَ، هَنَّأَ، سَمَّى، حَيَّى</span><span class="rule-table-ru">поприветствовал; прославил; поздравил; назвал; поприветствовал</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَرْفُ الزِّيَادَةِ</span><span class="rule-table-ru">добавочный элемент</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَضْعِيفُ الْعَيْنِ</span><span class="rule-table-ru">удвоение второй коренной буквы</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ</span><span class="rule-table-ru">масдар</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَفْعِيلٌ</span><span class="rule-table-ru">вес «таф‘иль»</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Масдар на весе تَفْعِيلٌ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفِعْلُ</span><span class="rule-table-ru">глагол и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ</span><span class="rule-table-ru">масдар и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سَلَّمَ</span><span class="rule-table-ru">поприветствовал</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَسْلِيمٌ</span><span class="rule-table-ru">приветствие</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">عَلَّمَ</span><span class="rule-table-ru">обучил</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَعْلِيمٌ</span><span class="rule-table-ru">обучение</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Масдар на весе تَفْعِلَةٌ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَبَبُ الْوَزْنِ</span><span class="rule-table-ru">причина формы</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفِعْلُ</span><span class="rule-table-ru">глагол</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ</span><span class="rule-table-ru">масдар и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلُّ اللَّامِ</span><span class="rule-table-ru">слабая третья коренная</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سَمَّى</span><span class="rule-table-ru">назвал</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَسْمِيَةٌ</span><span class="rule-table-ru">наименование</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلُّ اللَّامِ</span><span class="rule-table-ru">слабая третья коренная</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">رَبَّى</span><span class="rule-table-ru">воспитал</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَرْبِيَةٌ</span><span class="rule-table-ru">воспитание</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلُّ اللَّامِ</span><span class="rule-table-ru">слабая третья коренная</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">حَيَّى</span><span class="rule-table-ru">поприветствовал</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَحِيَّةٌ</span><span class="rule-table-ru">приветствие; исходная форма: تَحْيِيَةٌ</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَهْمُوزُ اللَّامِ</span><span class="rule-table-ru">хамза — третья коренная</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">هَنَّأَ</span><span class="rule-table-ru">поздравил</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَهْنِئَةٌ</span><span class="rule-table-ru">поздравление</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَهْمُوزُ اللَّامِ</span><span class="rule-table-ru">хамза — третья коренная</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وَطَّأَ</span><span class="rule-table-ru">подготовил</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَوْطِئَةٌ</span><span class="rule-table-ru">подготовка; введение</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَهْمُوزُ اللَّامِ</span><span class="rule-table-ru">хамза — третья коренная</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">جَزَّأَ</span><span class="rule-table-ru">разделил на части</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَجْزِئَةٌ</span><span class="rule-table-ru">разделение на части</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Производные формы بَابِ فَعَّلَ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَاضِي</span><span class="rule-table-ru">прошедшее</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُضَارِعُ</span><span class="rule-table-ru">настоящее-будущее</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْرُ</span><span class="rule-table-ru">повеление</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ</span><span class="rule-table-ru">масдар</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِسْمُ الْفَاعِلِ</span><span class="rule-table-ru">имя действующего</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِسْمُ الْمَفْعُولِ</span><span class="rule-table-ru">имя объекта действия</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سَجَّلَ</span><span class="rule-table-ru">записал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُسَجِّلُ</span><span class="rule-table-ru">записывает</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سَجِّلْ</span><span class="rule-table-ru">запиши</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَسْجِيلٌ</span><span class="rule-table-ru">запись</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُسَجِّلٌ</span><span class="rule-table-ru">записывающий</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُسَجَّلٌ</span><span class="rule-table-ru">записанный</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">صَلَّى</span><span class="rule-table-ru">совершил молитву; бросил в огонь</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُصَلِّي</span><span class="rule-table-ru">совершает молитву; бросает в огонь</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">صَلِّ</span><span class="rule-table-ru">соверши молитву</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صَلَاةٌ؛ تَصْلِيَةٌ</span><span class="rule-table-ru">молитва; бросание в огонь</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُصَلٍّ</span><span class="rule-table-ru">молящийся</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُصَلًّى</span><span class="rule-table-ru">то, над чем совершено действие; место молитвы определяется контекстом</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">هَدَّأَ</span><span class="rule-table-ru">успокоил</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُهَدِّئُ</span><span class="rule-table-ru">успокаивает</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">هَدِّئْ</span><span class="rule-table-ru">успокой</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَهْدِئَةٌ</span><span class="rule-table-ru">успокоение</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُهَدِّئٌ</span><span class="rule-table-ru">успокаивающий</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُهَدَّأٌ</span><span class="rule-table-ru">успокоенный</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Особенность صَلَّى</span><p class="rule-study-text"><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">صَلَّى بِمَعْنَى الْعِبَادَةِ: مَصْدَرُهُ غَيْرُ مُسْتَعْمَلٍ، وَلَهُ ٱسْمُ مَصْدَرٍ هُوَ صَلَاةٌ.</span> Когда «салля» означает поклонение, его обычный масдар не употребляется; вместо него используется имя масдара «салят».</p><p class="rule-study-text"><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">صَلَّى بِمَعْنَى أَلْقَاهُ فِي النَّارِ: مَصْدَرُهُ تَصْلِيَةٌ.</span> В значении «бросил его в Огонь» масдар — «таслия».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-structure" dir="rtl" lang="ar">﴿ وَتَصْلِيَةُ جَحِيمٍ ﴾</span><span class="rule-example-ru">«И горение в Аду».</span></div></div></div>', 4, 'rule', 'В модели «фа‘‘аля» добавкой служит удвоение второй коренной буквы; обычный масдар имеет вес «таф‘иль», а при слабой или хамзованной последней коренной — «таф‘иля».', 'حَرْفُ الزِّيَادَةِ فِي بَابِ فَعَّلَ تَضْعِيفُ الْعَيْنِ، وَمَصْدَرُهُ عَلَى وَزْنِ تَفْعِيلٍ. وَيَأْتِي عَلَى وَزْنِ تَفْعِلَةٍ إِذَا كَانَ الْفِعْلُ مُعْتَلَّ اللَّامِ أَوْ مَهْمُوزَ اللَّامِ.'),
    ('Мединский курс (Том 3)', '16', 'صِيَاغَةُ ٱسْمِ الْمَفْعُولِ وَٱسْمَيِ الزَّمَانِ وَالْمَكَانِ مِنْ غَيْرِ الثُّلَاثِيِّ (образование имени объекта, времени и места от нетрёхбуквенного глагола)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Образование форм</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الصِّيغَةُ</span><span class="rule-table-ru">форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَرْفُ الْمُضَارَعَةِ</span><span class="rule-table-ru">что делается с префиксом</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَا قَبْلَ الْآخِرِ</span><span class="rule-table-ru">огласовка перед последней буквой</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">اِسْمُ الْمَفْعُولِ</span><span class="rule-table-ru">имя объекта действия</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">مِيمٌ مَضْمُومَةٌ</span><span class="rule-table-ru">заменяется на мим с даммой</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَفْتُوحٌ</span><span class="rule-table-ru">получает фатху</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">اِسْمُ الزَّمَانِ</span><span class="rule-table-ru">имя времени</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">مِيمٌ مَضْمُومَةٌ</span><span class="rule-table-ru">заменяется на мим с даммой</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَفْتُوحٌ</span><span class="rule-table-ru">получает фатху</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">اِسْمُ الْمَكَانِ</span><span class="rule-table-ru">имя места</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">مِيمٌ مَضْمُومَةٌ</span><span class="rule-table-ru">заменяется на мим с даммой</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَفْتُوحٌ</span><span class="rule-table-ru">получает фатху</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اِسْمُ الْفَاعِلِ</span><span class="rule-table-ru">имя действующего</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">مِيمٌ مَضْمُومَةٌ</span><span class="rule-table-ru">заменяется на мим с даммой</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مَكْسُورٌ</span><span class="rule-table-ru">получает касру</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">الَّذِي يُمَيِّزُ بَيْنَ <span class="ar-tone-predicate">ٱسْمِ الْمَفْعُولِ</span> <span class="ar-tone-nasb">وَٱسْمَيِ الزَّمَانِ وَالْمَكَانِ</span> هُوَ <span class="ar-tone-structure">الْقَرِينَةُ اللَّفْظِيَّةُ أَوِ الْمَعْنَوِيَّةُ</span>.</span><p class="rule-study-text">Одинаковые по форме имя объекта, времени и места различаются по словесному или смысловому контексту.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Все контекстные примеры</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَوْعُ الصِّيغَةِ</span><span class="rule-table-ru">значение формы</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْقَرِينَةُ</span><span class="rule-table-ru">контекст</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هَذَا مُصَلَّى النِّسَاءِ.</span><span class="rule-table-ru">Это место молитвы женщин.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">اِسْمُ مَكَانٍ</span><span class="rule-table-ru">имя места</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النِّسَاءِ</span><span class="rule-table-ru">упоминание женщин указывает на место их молитвы</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفَجْرُ مُصَلًّى.</span><span class="rule-table-ru">Утренняя молитва совершена.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">اِسْمُ مَفْعُولٍ</span><span class="rule-table-ru">имя объекта действия</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفَجْرُ</span><span class="rule-table-ru">утренняя молитва выступает объектом действия</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْقُرْآنُ مُسَجَّلٌ فِي هَذَا الشَّرِيطِ.</span><span class="rule-table-ru">Коран записан на этой ленте.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">اِسْمُ مَفْعُولٍ</span><span class="rule-table-ru">имя объекта действия</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْقُرْآنُ</span><span class="rule-table-ru">Коран является записанным объектом</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هُنَا مُسَجَّلُ الطُّلَّابِ.</span><span class="rule-table-ru">Здесь место регистрации студентов.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">اِسْمُ مَكَانٍ</span><span class="rule-table-ru">имя места</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">هُنَا</span><span class="rule-table-ru">указание «здесь» определяет значение места</span></td></tr></tbody></table></div></div></div>', 5, 'rule', 'От нетрёхбуквенного глагола имя объекта, времени и места образуются заменой префикса настоящего времени на мим с даммой и фатхой перед последней буквой; конкретное значение определяет контекст.', 'يُصَاغُ ٱسْمُ الْمَفْعُولِ وَٱسْمَا الزَّمَانِ وَالْمَكَانِ مِنَ الْفِعْلِ غَيْرِ الثُّلَاثِيِّ الْمُجَرَّدِ بِإِبْدَالِ حَرْفِ الْمُضَارَعَةِ مِيمًا مَضْمُومَةً وَفَتْحِ مَا قَبْلَ الْآخِرِ. وَيُصَاغُ ٱسْمُ الْفَاعِلِ كَذَلِكَ، وَلَكِنْ بِكَسْرِ مَا قَبْلَ الْآخِرِ. وَتُمَيِّزُ بَيْنَ الْأَوَّلِ وَٱسْمَيِ الزَّمَانِ وَالْمَكَانِ الْقَرِينَةُ اللَّفْظِيَّةُ أَوِ الْمَعْنَوِيَّةُ.'),
    ('Мединский курс (Том 3)', '16', 'ضَمُّ أَحْرُفِ الْمُضَارَعَةِ فِي الْفِعْلِ الرُّبَاعِيِّ (дамма префиксов настоящего времени у четырёхбуквенного глагола)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">أَحْرُفُ الْمُضَارَعَةِ مِنَ الْفِعْلِ الرُّبَاعِيِّ تَكُونُ <span class="ar-tone-raf">مَضْمُومَةً</span>.</span><p class="rule-study-text">Префиксы настоящего-будущего времени у четырёхбуквенного глагола имеют дамму.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Все примеры шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفِعْلُ الْمَاضِي</span><span class="rule-table-ru">прошедшая форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفِعْلُ الْمُضَارِعُ</span><span class="rule-table-ru">форма настоящего-будущего</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">دَرَّسَ</span><span class="rule-table-ru">преподавал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُدَرِّسُ</span><span class="rule-table-ru">преподаёт</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">ضُمَّتِ الْيَاءُ</span><span class="rule-table-ru">буква йа получила дамму</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَكْرَمَ</span><span class="rule-table-ru">оказал почёт</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">نُكْرِمُ</span><span class="rule-table-ru">мы оказываем почёт</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">ضُمَّتِ النُّونُ</span><span class="rule-table-ru">буква нун получила дамму</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">زَلْزَلَ</span><span class="rule-table-ru">сотрясал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تُزَلْزِلُ</span><span class="rule-table-ru">она сотрясает</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">ضُمَّتِ التَّاءُ</span><span class="rule-table-ru">буква та получила дамму</span></td></tr></tbody></table></div></div></div>', 6, 'rule', 'У четырёхбуквенного глагола буква-префикс формы настоящего-будущего времени получает дамму.', 'أَحْرُفُ الْمُضَارَعَةِ مِنَ الْفِعْلِ الرُّبَاعِيِّ تَكُونُ مَضْمُومَةً.');

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'الأَفْعَالُ الْمُجَرَّدَةُ ، والْمَزِيدَةُ
الفعلُ الْمُجَرَّدُ ، هو : ما كانت جميعُ أُحْرُفِهِ أَصْلِيَّةً ، وهو نوعان :
1- مُجَرَّدٌ ثُلاَثِيٌّ ، نحو : خَرَجَ ، فَهِمَ ، كَرُمَ ، قَرَأَ ، سَعَى ، نَامَ ( جميع الأحرف الثَّلاثة
أصليَّة ) .
2- مُجَرَّدٌ رُبَاعِيٌّ ، نحو : وَسْوَسَ ، زَلْزَلَ ، بَعْثَرَ ، دَحْرَجَ ، تَرْجَمَ ( جميع الأحرف الأربعة أصليَّة ) .
الفعلُ الْمَزِيدُ ، هو : ما زِيدَ فيه حَرْفٌ ، أو أكثر على أحرفه الأصليّة ، وهو نوعان :
1- ثُلاَثِيٌ مَزِيدٌ ، نحو : سَلَّمَ ، أَسْلَمْ ، سَاعَدَ ،  تَقَبَّلَ ، اسْتَقْبَلَ .
2- رُبَاعِيٌ مَزِيدٌ ( سَتَدْرُسُ الرُّباعيَّ المجرَّدَ، والمزيدَ في الجزء الرَّابع إن شاء الله تعالى ) .', 65, 66, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '16' and sort_order = 1;

