  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'أوزانُ الثُّلاثِيِّ المزِيدِ : الثلاثي المزيد ثلاثة أقسام ، هي :
1- مَزِيد بحرف واحد              2- مَزِيد بحرفين             3- مَزِيد بثلاثة أحرف .
