  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'أَوَّلاً : بَـابُ فَعَّلَ
مِنْ أمْثِلَتِهِ : سَلَّمَ ، سَبَّحَ ، هَنَّأَ ، سَمَّى ، حَيَّى .
حرفُ الزَّيَادَةِ : تَضْعِيفُ العَيْنِ .
مَصْدَرُهُ : تَفْعِيلٌ ، نحو : سَلَّمَ : تَسْلِيم . عَلَّمَ : تَعْلِيم .
ويأتِي على وزن ( تَفْعِلَة ) إذا كان الفعلُ مُعتلَّ اللاَّم ، أو مهموز اللاَّم ، نحو :
سَمَّى : تَسْمِيَة . رَبَّى : تَرْبِيَة . حَيَّى : تَحِيَّة ( أصله : تَحْيِيَة ) .
ونحو : هَنَّأَ: تَهْنِئَة . وَطَّأَ : تَوْطِئَة . جَزَّأَ : تَجْزِئَة .
* جدولٌ يُبَيَّنُ مُشْتَقَّاتِ بابِ فَعَّلَ .
