  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', '* صِيَاغَةُ اسمِ المفعولِ ، واسمي الزّمان والمكان من الفعل غير الثُّلاثيِّ المجرّدِ ،كما يلي:
إِبْدَالُ حرفِ المضارعةِ ميماً مضمومةً ، وفتحُ ما قبل الآخِر . وكذلك اسم الفاعل ولكنْ بكَسْرِ ما قبل الآخِر .
والَّذي يُمَيَّزُ بين اسم المفعول ، واسمي الزَّمانِ والمكانِ القَرِينَةُ ( لَفْظِيَّة ، أو مَعْنَويّة ) .
* فإذا قلت : هذا مُصَلَّى النَّسَاءِ ، فهو اسم مكان .
وإذا قُلْتَ : الفَجْرُ مُصَلًّى ، فهو اسم مفعول .
* وإذا قلت : القرآنُ مُسَجَّلٌ في هذا الشريط ، فهو اسم مفعول .
وإذا قلتَ : هُنا مُسَجَّلُ الطُّلاب ، فهو اسم مكان .', 67, 68, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '16' and sort_order = 5;

