  select id, 'Sharkh_Medinskiy_3.pdf', '* أَحرفُ المضارعةِ من الفعلِ الرُّباعيِّ تكونُ مضمومةً ، نحو : دَرَّسَ : يُدَرَّسُ .
أَكْرَمَ : نُكْرِمُ   .   زَلْزَلَ : تُزَلْزِلُ .', 68, 68, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '16' and sort_order = 6;

  select count(*) into new_rule_count from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '16';
  select count(*) into source_count from public.rule_sources rs join public.rules r on r.id = rs.rule_id where r.course_name = 'Мединский курс (Том 3)' and r.lesson_number = '16';
  if new_rule_count <> 6 or source_count <> 6 then raise exception 'Book 3 lesson 16 verification failed: rules %, sources %', new_rule_count, source_count; end if;
end
$migration$;
commit;
